function mobileMenu(){var x=document.getElementById("mobileMenu");-1==x.className.indexOf("w3-show")?x.className+=" w3-show":x.className=x.className.replace(" w3-show","")}const startYear=2026,currentYear=(new Date).getFullYear(),yearText=currentYear>2026?`2026-${currentYear}`:"2026";function myAccordion(btn){var panel=btn.nextElementSibling;-1==panel.className.indexOf("w3-show")?(panel.className+=" w3-show",panel.previousElementSibling.className+=" w3-dark-grey"):(panel.className=panel.className.replace(" w3-show",""),panel.previousElementSibling.className=panel.previousElementSibling.className.replace(" w3-dark-grey",""))}document.getElementById("copyright-year").textContent=yearText;